import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class MessageResponseTimeoutException extends BaseException {
    constructor() {
        super(
            'Network.MessageResponseTimeout',
            'Device has lost connection, attempting to reconnect.'
        );
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);

        switch (locale) {
            case 'it-it':
                this.displayMessage = 'Il tuo dispositivo ha perso la connessione, attendi mentre proviamo a riconnetterti';
                break;
            case 'es-es':
                this.displayMessage = '¡Vaya! Parece que no hay conexión. Comprueba tu internet, reconéctate e inténtalo de nuevo.';
                break;
            default:
                this.displayMessage = this.message;
        }
    }
}
